def _key_value_items(facts: Dict[str, Any], exclude: Optional[set] = None) -> List[Dict[str, str]]:
    skip = exclude or set()
    items: List[Dict[str, str]] = []
    for key, value in facts.items():
        if key in skip or key.startswith("_") or key.startswith("pfs_"):
            continue
        if isinstance(value, (list, dict)):
            continue
        label = key.replace("_", " ").title()
        items.append({"label": label, "value": str(value)})
    return items[:20]


def _cards_from_numeric_facts(
    facts: Dict[str, Any],
    *,
    limit: int = 4,
    skip: Optional[set] = None,
) -> List[ReportMetricCard]:
    skip = skip or set()
    cards: List[ReportMetricCard] = []
    for key, value in facts.items():
        if key in skip or key.startswith("_") or key.startswith("pfs_"):
            continue
        if isinstance(value, (int, float)) and _MONEY_KEYWORDS.search(key):
            cards.append(ReportMetricCard(label=key.replace("_", " ").title(), value=float(value), format="currency"))
        if len(cards) >= limit:
            break
    return cards


def _parse_rent_roll_rows(table_rows: List[str]) -> List[Dict[str, Any]]:
    import re as _re

    money = _re.compile(r"[\$]?\s*([\d,]+(?:\.\d{2})?)")
    rows: List[Dict[str, Any]] = []
    for line in table_rows:
        if "rent" not in line.lower() and "tenant" not in line.lower() and "|" not in line:
            continue
        parts = [p.strip() for p in line.split("|")]
        label = parts[0] if parts else line
        rent = 0.0
        for part in parts[1:] + [line]:
            for match in money.finditer(part):
                try:
                    rent = float(match.group(1).replace(",", ""))
                except ValueError:
                    continue
        rows.append({"label": label[:80], "Unit / Tenant": label[:80], "Rent": rent, "Details": " | ".join(parts[1:3])[:80]})
    return rows

